-- ORMEN Atelier: showcase models (Chester, modern, İskandinav, blok, puflar). GENERATED by scripts/build-showcase-sql.ts; do not edit by hand.
-- Paste into the Supabase SQL editor and press Run. Run supabase/veri/2-kumaslar-misso.sql first (default fabrics).
-- Running it again is safe: missing models are added; existing ones keep their shape and name
-- (they may have been edited in the panel) and only get this version's order and default fabric.
-- Models taken off the showcase are switched off (not deleted: can be switched back on in the panel).

update public.models set is_active = false where firm_id is null and slug in ('sezlonglu-kose', 'u-koltuk');

update public.models m set default_fabric_code = v.fabric, sort_order = v.sort_order
from (values
  ('chester-kanepe', 'PIETRA-05', 3),
  ('chester-berjer', 'PIETRA-03', 4),
  ('modern-uclu', 'SIENA-02', 5),
  ('iskandinav-ikili', 'LUMA-04', 6),
  ('blok-dortlu', 'VERSO-03', 7),
  ('puf', 'SIENA-05', 8),
  ('yuvarlak-puf', 'LUMA-05', 9)
) as v (slug, fabric, sort_order)
where m.firm_id is null and m.slug = v.slug;

insert into public.models (firm_id, slug, name, procedural_key, params, fabric_material_names, width_cm, depth_cm, height_cm, default_fabric_code, is_active, sort_order)
select null, v.slug, v.name, 'parametric', v.params::jsonb, string_to_array(v.materials, ','), v.w, v.d, v.h, v.fabric, v.active, v.sort_order
from (values
  ('chester-kanepe', 'Chester Kanepe', '{"tip":"uclu","kol":"kivrik","sirt":"alcak","ayak":"konik","genislikCm":220,"derinlikCm":92,"sirtTipi":"kapitone","yukseklikCm":76}', 'kumas', 220, 92, 76, 'PIETRA-05', true, 3),
  ('chester-berjer', 'Kulaklı Chester Berjer', '{"tip":"berjer","kol":"kivrik","sirt":"alcak","ayak":"konik","genislikCm":82,"derinlikCm":88,"sirtTipi":"kapitone","kulak":true,"yukseklikCm":104}', 'kumas', 82, 88, 104, 'PIETRA-03', true, 4),
  ('modern-uclu', 'Modern Üçlü', '{"tip":"uclu","kol":"ince","sirt":"orta","ayak":"metal","genislikCm":232,"derinlikCm":96,"oturumTipi":"tek","yukseklikCm":80}', 'kumas', 232, 96, 80, 'SIENA-02', true, 5),
  ('iskandinav-ikili', 'İskandinav İkili', '{"tip":"ikili","kol":"yuvarlak","sirt":"orta","ayak":"konik","genislikCm":176,"derinlikCm":88,"yukseklikCm":84}', 'kumas', 176, 88, 84, 'LUMA-04', true, 6),
  ('blok-dortlu', 'Blok Dörtlü Kanepe', '{"tip":"dortlu","kol":"kalin","sirt":"alcak","ayak":"gizli","genislikCm":300,"derinlikCm":104,"sirtTipi":"sabit","yukseklikCm":74}', 'kumas', 300, 104, 74, 'VERSO-03', true, 7),
  ('puf', 'Puf', '{"tip":"puf","kol":"yok","sirt":"alcak","ayak":"konik","genislikCm":90,"derinlikCm":60,"yukseklikCm":42}', 'kumas', 90, 60, 42, 'SIENA-05', true, 8),
  ('yuvarlak-puf', 'Yuvarlak Puf', '{"tip":"puf","kol":"yok","sirt":"alcak","ayak":"konik","genislikCm":60,"derinlikCm":60,"form":"yuvarlak","yukseklikCm":44}', 'kumas', 60, 60, 44, 'LUMA-05', true, 9)
) as v (slug, name, params, materials, w, d, h, fabric, active, sort_order)
where not exists (select 1 from public.models m where m.firm_id is null and m.slug = v.slug);
